/* Quiet Frame: Settings profile, simple navigation icons, header + recent 3 */
.finder-avatar:not([src]) { display: none; }
.finder-nav-list a { position: relative; padding-left: 29px; }
.finder-nav-list a::before { content: ''; position: absolute; left: 8px; top: 50%; width: 12px; height: 14px; margin: -7px 0 0; border: 1px solid #91acc4; border-radius: 2px; background: transparent; }
.finder-nav-list a::after { content: ''; position: absolute; left: 11px; top: 50%; width: 6px; height: 1px; margin-top: -3px; background: #91acc4; box-shadow: 0 3px 0 #91acc4, 0 6px 0 #91acc4; }
.finder-nav-list li:nth-child(2) a::before { width: 14px; height: 11px; margin-top: -5.5px; border-radius: 2px; }
.finder-nav-list li:nth-child(2) a::after { left: 11px; width: 7px; height: 7px; margin-top: -1px; background: transparent; border-top: 1px solid #91acc4; border-left: 1px solid #91acc4; transform: rotate(45deg); box-shadow: none; }
.finder-nav-list li:nth-child(3) a::before { height: 12px; margin-top: -6px; border-radius: 1px 1px 4px 1px; }
.finder-nav-list li:nth-child(3) a::after { margin-top: -2px; box-shadow: 0 3px 0 #91acc4; }
.finder-nav-group:last-child .finder-nav-list a::before, .finder-nav-group:last-child .finder-nav-list a::after { width: 9px; height: 6px; border: 1px solid #91acc4; border-radius: 4px; background: transparent; box-shadow: none; transform: rotate(-40deg); }
.finder-nav-group:last-child .finder-nav-list a::before { left: 8px; margin-top: -1px; }
.finder-nav-group:last-child .finder-nav-list a::after { left: 13px; margin-top: -5px; }
.finder-home-main.finder-home-composed { display: flex; flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 32px; padding: 36px 42px 32px; min-height: 570px; }
.finder-hero { position: relative; flex: 0 0 auto; width: 100%; overflow: visible; margin: 0; border: 0; background: transparent; }
.finder-hero > :only-child { display: block; max-width: 100%; margin-left: auto; margin-right: auto; border-radius: 3px; background: #edf0f3; outline: 1px solid #e1e3e6; outline-offset: -1px; }
.finder-hero-image { display: block; width: 100%; max-width: 100%; height: auto; object-fit: cover; object-position: center; }
.finder-hero-image[hidden] { display: none; }
.finder-recent-section { width: 100%; margin-top: 0; }
.finder-recent-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; margin-bottom: 12px; }
.finder-recent-head h1 { margin: 0; font-size: 14px; line-height: 1.5; font-weight: 600; letter-spacing: -.02em; }
.finder-recent-head > span { color: var(--finder-muted); font-size: 8px; letter-spacing: .12em; }
.finder-home-recent-list > li:nth-child(n+4) { display: none; }
.finder-home-recent-list > li:nth-child(3) { border-bottom: 1px solid var(--finder-line); }
.finder-home-recent-entry { padding: 11px 0; gap: 10px; }
.finder-home-recent-meta strong { font-size: 11px; }
.finder-home-recent-meta small { font-size: 9px; }
@media (max-width: 720px) {
  .finder-nav-list a { padding-left: 23px; }
  .finder-nav-list a::before { left: 2px; }
  .finder-nav-list a::after, .finder-nav-list li:nth-child(2) a::after { left: 5px; }
  .finder-nav-group:last-child .finder-nav-list a::before { left: 2px; }
  .finder-nav-group:last-child .finder-nav-list a::after { left: 7px; }
  .finder-home-main.finder-home-composed { padding: 24px 20px 26px; gap: 28px; min-height: 390px; }
  .finder-recent-head h1 { font-size: 13px; }
  .finder-home-recent-meta strong { font-size: 11px; }
}

